// 3D model of the skull base from Z-Anatomy meshes (CC BY-SA 4.0, based on
// BodyParts3D): bones of both sides with the vault removed, the brainstem,
// chiasm and pituitary, and the right-sided cranial nerves, arteries and
// dural sinuses. Geometry and the traced courses live in
// data/skull-base-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred in the midline at the petrous bones:
// +y = superior, +z = anterior, and the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.skull_base = {
  // Default view: looking down into the skull base from above and behind the
  // right side, anterior at the top (the patient's right is on the right).
  camera: { target: [-0.6, 0.4, 0.6], radius: 30, theta: 3.45, phi: 0.72 },

  // [theta, phi] for the view buttons. "Lateral" shows the right side (-x).
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-0.15, 2.75],
    anterior: [Math.PI, 0.12]
  },
  viewLabels: { inferior: "From below", anterior: "From above" },

  // Starting axial level (0 = bottom of the model, 1 = top): the petrous bones.
  sectionLevel: 0.62,

  look: {
    occipital: { kind: "bone" },
    sphenoid: { kind: "bone", color: 0xe6d6b4 },
    temporal: { kind: "bone", color: 0xe9dcc0 },
    ethmoid: { kind: "bone", color: 0xe3d2ae },
    frontal: { kind: "bone" },
    atlas_axis: { kind: "bone" },
    facial_skeleton: { kind: "bone", opacity: 0.85 },
    mandible: { kind: "bone", opacity: 0.85 },
    brainstem: { kind: "gland", color: 0xd8b0a6 },
    optic_chiasm: { kind: "nerve", color: 0xf0d27a },
    pituitary: { kind: "gland", color: 0xd9906e },
    tentorium: { kind: "cartilage", color: 0xc8c2d8, opacity: 0.45 },
    cn1: { kind: "nerve" },
    cn2: { kind: "nerve" },
    cn3: { kind: "nerve" },
    cn4: { kind: "nerve" },
    cn5: { kind: "nerve", color: 0xf2c94c },
    v1: { kind: "nerve" },
    v2: { kind: "nerve" },
    v3: { kind: "nerve" },
    cn6: { kind: "nerve" },
    cn7: { kind: "nerve" },
    chorda: { kind: "nerve" },
    cn8: { kind: "nerve" },
    cn9: { kind: "nerve" },
    cn10: { kind: "nerve" },
    cn11: { kind: "nerve" },
    cn12: { kind: "nerve" },
    ica: { kind: "artery" },
    vertebral: { kind: "artery" },
    basilar: { kind: "artery" },
    pca: { kind: "artery" },
    cerebellar_arteries: { kind: "artery" },
    anterior_circulation: { kind: "artery" },
    ophthalmic_artery: { kind: "artery" },
    middle_meningeal: { kind: "artery" },
    maxillary_artery: { kind: "artery" },
    cavernous_sinus: { kind: "vein", opacity: 0.55 },
    sigmoid_sinus: { kind: "vein" },
    petrosal_sinuses: { kind: "vein" },
    ijv: { kind: "vein" }
  },

  build(THREE, h) {
    return h.fromMeshes("skull_base", this.look);
  }
};
